package com.bank.loyalty;

import java.util.logging.Logger;

public class LoyaltyLadderCounter {

    private static final Logger log = Logger.getLogger(LoyaltyLadderCounter.class.getName());

    // Ways to climb n tiers taking 1 or 2 at a time
    public long countWays(int n) {
        if (n <= 1) return 1;
        long prev2 = 1, prev1 = 1;                     // dp[0]=1, dp[1]=1
        for (int i = 2; i <= n; i++) {
            long cur = prev1 + prev2;                  // dp[i] = dp[i-1] + dp[i-2]
            prev2 = prev1; prev1 = cur;
        }
        final long ways = prev1;
        log.info(() -> "Distinct progression paths to tier " + n + " = " + ways);
        return prev1;
    }
}
