package com.bank.loyalty;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class ClimbStairsDemo {

    private static final Logger log = Logger.getLogger(ClimbStairsDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Loyalty Ladder Path Counter (Climbing Stairs)");
        LoyaltyLadderCounter counter = new LoyaltyLadderCounter();
        log.info("n=5 → " + counter.countWays(5)); // 8
    }
}
